/* eslint-disable @typescript-eslint/no-explicit-any -- faithful copies of the SDK declarations */
/**
 * Vendored type definitions from `@earendil-works/pi-coding-agent` (v0.84.2).
 *
 * The app only ever consumed the SDK's *types* (the agent runtime lives in the
 * OMP worker via `omp --mode rpc`, not here), so the dependency was stripped
 * and the declarations the UI actually renders are kept here as the source of
 * truth. Shapes mirror the SDK declarations verbatim; if the wire format
 * changes, update them here.
 */

import type { AgentEvent, AgentMessage, ThinkingLevel } from './pi-agent-core'
import type { ImageContent, Model, TextContent, Usage } from './pi-ai'

// ---------------------------------------------------------------------------
// Resource metadata (core/package-manager.d.ts, core/source-info.d.ts)
// ---------------------------------------------------------------------------

export type SourceScope = 'user' | 'project' | 'temporary'
export type SourceOrigin = 'package' | 'top-level'

export interface SourceInfo {
  path: string
  source: string
  scope: SourceScope
  origin: SourceOrigin
  baseDir?: string
}

export interface PathMetadata {
  source: string
  scope: SourceScope
  origin: 'package' | 'top-level'
  baseDir?: string
}

/** SDK package shapes (core/package-manager). */
export interface ResolvedResource {
  path: string
  enabled: boolean
  metadata: PathMetadata
}

export interface ResolvedPaths {
  extensions: ResolvedResource[]
  skills: ResolvedResource[]
  prompts: ResolvedResource[]
  themes: ResolvedResource[]
}

// ---------------------------------------------------------------------------
// Skills & prompt templates (core/skills.d.ts, core/prompt-templates.d.ts)
// ---------------------------------------------------------------------------

export interface Skill {
  name: string
  description: string
  filePath: string
  baseDir: string
  sourceInfo: SourceInfo
  disableModelInvocation: boolean
}

/** Represents a prompt template loaded from a markdown file. */
export interface PromptTemplate {
  name: string
  description: string
  argumentHint?: string
  content: string
  sourceInfo: SourceInfo
  filePath: string
}

// ---------------------------------------------------------------------------
// Custom messages (core/messages.d.ts)
// ---------------------------------------------------------------------------

export type {
  BashExecutionMessage,
  BranchSummaryMessage,
  CompactionSummaryMessage,
  CustomMessage,
} from './pi-agent-core'

// ---------------------------------------------------------------------------
// Session entries (core/session-manager.d.ts)
// ---------------------------------------------------------------------------

export interface SessionHeader {
  type: 'session'
  version?: number
  id: string
  timestamp: string
  cwd: string
  parentSession?: string
}

export interface SessionEntryBase {
  type: string
  id: string
  parentId: string | null
  timestamp: string
}

export interface SessionMessageEntry extends SessionEntryBase {
  type: 'message'
  message: AgentMessage
}

export interface ThinkingLevelChangeEntry extends SessionEntryBase {
  type: 'thinking_level_change'
  thinkingLevel: string
}

export interface ModelChangeEntry extends SessionEntryBase {
  type: 'model_change'
  provider: string
  modelId: string
}

export interface CompactionEntry<T = unknown> extends SessionEntryBase {
  type: 'compaction'
  summary: string
  firstKeptEntryId: string
  tokensBefore: number
  /** Extension-specific data (e.g., ArtifactIndex, version markers for structured compaction) */
  details?: T
  /** Usage from the LLM call(s) that generated this summary, if available */
  usage?: Usage
  /** True if generated by an extension, undefined/false if pi-generated (backward compatible) */
  fromHook?: boolean
}

export interface BranchSummaryEntry<T = unknown> extends SessionEntryBase {
  type: 'branch_summary'
  fromId: string
  summary: string
  /** Extension-specific data (not sent to LLM) */
  details?: T
  /** Usage from the LLM call that generated this summary, if available */
  usage?: Usage
  /** True if generated by an extension, false if pi-generated */
  fromHook?: boolean
}

/**
 * Custom entry for extensions to store extension-specific data in the session.
 * Does NOT participate in LLM context (ignored by buildSessionContext).
 */
export interface CustomEntry<T = unknown> extends SessionEntryBase {
  type: 'custom'
  customType: string
  data?: T
}

/** Label entry for user-defined bookmarks/markers on entries. */
export interface LabelEntry extends SessionEntryBase {
  type: 'label'
  targetId: string
  label: string | undefined
}

/** Session metadata entry (e.g., user-defined display name). */
export interface SessionInfoEntry extends SessionEntryBase {
  type: 'session_info'
  name?: string
}

/**
 * Custom message entry for extensions to inject messages into LLM context.
 * Unlike CustomEntry, this DOES participate in LLM context.
 */
export interface CustomMessageEntry<T = unknown> extends SessionEntryBase {
  type: 'custom_message'
  customType: string
  content: string | (TextContent | ImageContent)[]
  details?: T
  display: boolean
}

/** Session entry - has id/parentId for tree structure (returned by "read" methods in SessionManager). */
export type SessionEntry =
  | SessionMessageEntry
  | ThinkingLevelChangeEntry
  | ModelChangeEntry
  | CompactionEntry
  | BranchSummaryEntry
  | CustomEntry
  | CustomMessageEntry
  | LabelEntry
  | SessionInfoEntry

/** Tree node for getTree() - defensive copy of session structure. */
export interface SessionTreeNode {
  entry: SessionEntry
  children: SessionTreeNode[]
  /** Resolved label for this entry, if any */
  label?: string
  /** Timestamp of the latest label change for this entry, if any */
  labelTimestamp?: string
}

export interface SessionContext {
  messages: AgentMessage[]
  thinkingLevel: string
  model: {
    provider: string
    modelId: string
  } | null
}

export interface SessionInfo {
  path: string
  id: string
  /** Working directory where the session was started. Empty string for old sessions. */
  cwd: string
  /** User-defined display name from session_info entries. */
  name?: string
  /** Path to the parent session (if this session was forked). */
  parentSessionPath?: string
  created: Date
  modified: Date
  messageCount: number
  firstMessage: string
  allMessagesText: string
}

// ---------------------------------------------------------------------------
// Agent session (core/agent-session.d.ts, core/compaction/compaction.d.ts)
// ---------------------------------------------------------------------------

export interface CompactionResult<T = unknown> {
  summary: string
  firstKeptEntryId: string
  tokensBefore: number
  estimatedTokensAfter?: number
  /** Usage from the LLM call(s) that generated this summary, if available */
  usage?: Usage
  /** Extension-specific data (e.g., ArtifactIndex, version markers for structured compaction) */
  details?: T
}

/** Estimated context window usage. */
export interface ContextUsage {
  /** Estimated context tokens, or null if unknown (e.g. right after compaction, before next LLM response). */
  tokens: number | null
  contextWindow: number
  /** Context usage as percentage of context window, or null if tokens is unknown. */
  percent: number | null
}

/** Where user input came from. */
export type InputSource = 'interactive' | 'rpc' | 'extension'

/** Options for AgentSession.prompt(). */
export interface PromptOptions {
  /** Whether to dispatch extension commands and expand skill commands and prompt templates (default: true) */
  expandPromptTemplates?: boolean
  /** Image attachments */
  images?: ImageContent[]
  /** When streaming, how to queue the message: "steer" (interrupt) or "followUp" (wait). Required if streaming. */
  streamingBehavior?: 'steer' | 'followUp'
  /** Source of input for extension input event handlers. Defaults to "interactive". */
  source?: InputSource
  /** Internal hook used by RPC mode to observe prompt preflight acceptance or rejection. */
  preflightResult?: (success: boolean) => void
}

/** Result from cycleModel(). */
export interface ModelCycleResult {
  model: Model<any>
  thinkingLevel: ThinkingLevel
  /** Whether cycling through scoped models (--models flag) or all available */
  isScoped: boolean
}

/** Session statistics for /session command. */
export interface SessionStats {
  sessionFile: string | undefined
  sessionId: string
  userMessages: number
  assistantMessages: number
  toolCalls: number
  toolResults: number
  totalMessages: number
  tokens: {
    input: number
    output: number
    cacheRead: number
    cacheWrite: number
    total: number
  }
  cost: number
  contextUsage?: ContextUsage
}

/**
 * Session-specific events: the core AgentEvent with `agent_end` widened by a
 * `willRetry` flag, plus the coding agent's extra event kinds.
 */
export type AgentSessionEvent =
  | Exclude<AgentEvent, { type: 'agent_end' }>
  | {
      type: 'agent_end'
      messages: AgentMessage[]
      willRetry: boolean
    }
  | {
      type: 'agent_settled'
    }
  | {
      type: 'queue_update'
      steering: readonly string[]
      followUp: readonly string[]
    }
  | {
      type: 'compaction_start'
      reason: 'manual' | 'threshold' | 'overflow'
    }
  | {
      type: 'entry_appended'
      entry: SessionEntry
    }
  | {
      type: 'session_info_changed'
      name: string | undefined
    }
  | {
      type: 'model_changed'
    }
  | {
      type: 'thinking_level_changed'
      level: ThinkingLevel
    }
  | {
      type: 'compaction_end'
      reason: 'manual' | 'threshold' | 'overflow'
      result: CompactionResult | undefined
      aborted: boolean
      willRetry: boolean
      errorMessage?: string
    }
  | {
      type: 'auto_retry_start'
      attempt: number
      maxAttempts: number
      delayMs: number
      errorMessage: string
    }
  | {
      type: 'auto_retry_end'
      success: boolean
      attempt: number
      finalError?: string
    }
  | {
      type: 'summarization_retry_scheduled'
      attempt: number
      maxAttempts: number
      delayMs: number
      errorMessage: string
    }
  | {
      type: 'summarization_retry_attempt_start'
      source: 'branchSummary'
    }
  | {
      type: 'summarization_retry_attempt_start'
      source: 'compaction'
      reason: 'manual' | 'threshold' | 'overflow'
    }
  | {
      type: 'summarization_retry_finished'
    }
  | {
      type: 'bash_execution_update'
      id?: string
      delta: string
    }
  | {
      type: 'goal_updated'
      goal: SessionGoalSnapshot | null
    }

/**
 * OMP goal 运行时快照（goal_updated 事件帧 / state.goal 的 goal 字段）。
 * 数据来自 RPC JSON，字段以外来数据对待，UI 侧需防御式解析。
 */
export interface SessionGoalSnapshot {
  id: string
  objective: string
  status: 'active' | 'paused' | 'budget-limited' | 'complete' | 'dropped' | (string & {})
  tokenBudget?: number
  tokensUsed: number
  timeUsedSeconds: number
  createdAt: number
  updatedAt: number
}
